using System.Security.Claims; using Marina.Domain.Security; using Marina.Persistence.Data; using Marina.Persistence.Identity; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace Marina.Api.Controllers;
[ApiController,Authorize(Policy="StaffMfa"),Route("api/v1/admin/access"),Microsoft.AspNetCore.RateLimiting.EnableRateLimiting("admin")]
public sealed class AdminUsersController(UserManager<AppUser>users,RoleManager<IdentityRole<Guid>>roles,MarinaDbContext db):ControllerBase{public sealed record RolesRequest(List<string>Roles);public sealed record PermissionRequest(List<Guid>PermissionIds);
 [HttpGet("users"),Authorize(Policy="Users.Manage")]public async Task<ActionResult>UserList([FromQuery]string?search=null,[FromQuery]int page=1,[FromQuery]int pageSize=30){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var q=users.Users.AsNoTracking();if(!string.IsNullOrWhiteSpace(search)){var term=search.Trim();q=q.Where(x=>x.Email!.Contains(term)||x.DisplayName.Contains(term));}var total=await q.CountAsync();return Ok(new{items=await q.OrderBy(x=>x.Email).Skip((page-1)*pageSize).Take(pageSize).Select(x=>new{x.Id,x.Email,x.DisplayName,x.IsActive,x.TwoFactorEnabled,x.LockoutEnd,x.LastLoginUtc}).ToListAsync(),page,pageSize,total});}
 [HttpPut("users/{id:guid}/roles"),Authorize(Policy="Roles.Manage")]public async Task<IActionResult>SetRoles(Guid id,RolesRequest r){await using var transaction=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var user=await users.FindByIdAsync(id.ToString())??throw new KeyNotFoundException("User not found.");var current=await users.GetRolesAsync(user);var requested=r.Roles.Distinct(StringComparer.OrdinalIgnoreCase).ToList();if(id==UserId()&&requested.Except(current,StringComparer.OrdinalIgnoreCase).Any(x=>x!="Customer"))return Forbid();if(id==UserId()&&current.Contains("SuperAdmin")&&!requested.Contains("SuperAdmin"))return Conflict(new{message="You cannot remove your own SuperAdmin role."});if(current.Contains("SuperAdmin")&&!requested.Contains("SuperAdmin")&&await CountSuperAdmins()==1)return Conflict(new{message="The final SuperAdmin cannot be demoted."});foreach(var role in requested)if(!await roles.RoleExistsAsync(role))return BadRequest(new{message=$"Unknown role: {role}"});var removed=await users.RemoveFromRolesAsync(user,current.Except(requested,StringComparer.OrdinalIgnoreCase));if(!removed.Succeeded)return BadRequest(removed.Errors);var added=await users.AddToRolesAsync(user,requested.Except(current,StringComparer.OrdinalIgnoreCase));if(!added.Succeeded)return BadRequest(added.Errors);user.RequiresMfa=requested.Any(x=>x!="Customer");var updated=await users.UpdateAsync(user);if(!updated.Succeeded)return BadRequest(updated.Errors);await db.UserSessions.Where(x=>x.UserId==id&&x.RevokedUtc==null).ExecuteUpdateAsync(x=>x.SetProperty(s=>s.RevokedUtc,DateTime.UtcNow));Audit("Users.RolesChanged",id,new{before=current,after=requested});await db.SaveChangesAsync();await transaction.CommitAsync();return NoContent();}
 [HttpPut("users/{id:guid}/active"),Authorize(Policy="Users.Manage")]public async Task<IActionResult>SetActive(Guid id,SetUserActiveRequest request){await using var transaction=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var active=request.Active!.Value;if(id==UserId()&&!active)return Conflict(new{message="You cannot disable your own account."});var user=await users.FindByIdAsync(id.ToString())??throw new KeyNotFoundException();if(!active&&await users.IsInRoleAsync(user,"SuperAdmin")&&await CountSuperAdmins()==1)return Conflict(new{message="The final SuperAdmin cannot be disabled."});user.IsActive=active;var update=await users.UpdateAsync(user);if(!update.Succeeded)return BadRequest(update.Errors);if(!active)await db.UserSessions.Where(x=>x.UserId==id&&x.RevokedUtc==null).ExecuteUpdateAsync(x=>x.SetProperty(s=>s.RevokedUtc,DateTime.UtcNow));Audit("Users.ActiveChanged",id,new{active});await db.SaveChangesAsync();await transaction.CommitAsync();return NoContent();}
 [HttpGet("roles"),Authorize(Policy="Roles.Manage")]public async Task<ActionResult>RoleList()=>Ok(await roles.Roles.AsNoTracking().Select(x=>new{x.Id,x.Name,Permissions=db.RolePermissions.Where(p=>p.RoleId==x.Id).Join(db.Permissions,p=>p.PermissionId,p=>p.Id,(rp,p)=>p.Name)}).ToListAsync());
 [HttpPut("roles/{id:guid}/permissions"),Authorize(Policy="Roles.Manage")]public async Task<IActionResult>SetPermissions(Guid id,PermissionRequest r){await using var transaction=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var role=await roles.FindByIdAsync(id.ToString());if(role is null)return NotFound();var valid=await db.Permissions.Where(x=>r.PermissionIds.Contains(x.Id)).Select(x=>x.Id).ToListAsync();if(valid.Count!=r.PermissionIds.Distinct().Count())return BadRequest();if(role.Name=="SuperAdmin"&&!await db.Permissions.Where(x=>valid.Contains(x.Id)).Select(x=>x.Name).ContainsAsync("Roles.Manage"))return Conflict(new{message="SuperAdmin must retain Roles.Manage."});if(role.Name=="SuperAdmin"&&!await db.Permissions.Where(x=>valid.Contains(x.Id)).Select(x=>x.Name).ContainsAsync("Users.Manage"))return Conflict(new{message="SuperAdmin must retain Users.Manage."});db.RolePermissions.RemoveRange(db.RolePermissions.Where(x=>x.RoleId==id));db.RolePermissions.AddRange(valid.Select(x=>new RolePermission{RoleId=id,PermissionId=x}));await db.UserSessions.Where(s=>db.UserRoles.Any(r=>r.RoleId==id&&r.UserId==s.UserId)).ExecuteUpdateAsync(set=>set.SetProperty(s=>s.RevokedUtc,DateTime.UtcNow));Audit("Roles.PermissionsChanged",id,new{permissions=valid});await db.SaveChangesAsync();await transaction.CommitAsync();return NoContent();}
 private async Task<int>CountSuperAdmins(){var role=await roles.FindByNameAsync("SuperAdmin");return role is null?0:await db.UserRoles.CountAsync(x=>x.RoleId==role.Id&&db.Users.Any(u=>u.Id==x.UserId&&u.IsActive));}private void Audit(string action,Guid id,object value)=>db.AuditLogs.Add(new AuditLog{UserId=UserId(),Action=action,EntityName="AccessControl",EntityId=id.ToString(),IpAddress=HttpContext.Connection.RemoteIpAddress?.ToString()??"unknown",CorrelationId=HttpContext.TraceIdentifier,NewValuesJson=System.Text.Json.JsonSerializer.Serialize(value)});private Guid UserId()=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);}
